#!/usr/bin/env bash
# User-run capture only. No robot commands, launches, serial access or ROS setup.
# Filename and split names are generated by rosbag; no name argument required.
# Optional first argument changes the destination directory.
set -eu

capture_dir="${1:-$HOME/rosbag/year2026/10Oct/261030/inspection}"
mkdir -p -- "$capture_dir"
cd -- "$capture_dir"

exec rosbag record --buffsize=64 --split --duration=5m \
  /gimbalrotor/imu \
  /gimbalrotor/servo/states \
  /gimbalrotor/motor_pwms \
  /gimbalrotor/rpy/pid \
  /gimbalrotor/servo/target_states_debug \
  /gimbalrotor/servo/torque_states \
  /gimbalrotor/flight_state \
  /rosout
